CREATE TABLE roles (name VARCHAR(20) PRIMARY KEY, description VARCHAR(255) NOT NULL);
INSERT INTO roles VALUES ('STUDENT','Completes networking assignments'),('FACULTY','Manages assignments and grades submissions'),('ADMIN','Manages the platform');
ALTER TABLE users ADD CONSTRAINT users_role_fk FOREIGN KEY (role) REFERENCES roles(name);
ALTER TABLE users ADD COLUMN tokens_valid_after TIMESTAMPTZ;
ALTER TABLE users ADD COLUMN auth_version UUID NOT NULL DEFAULT gen_random_uuid();
CREATE UNIQUE INDEX users_normalized_email_idx ON users(lower(email));
ALTER TABLE assignments ADD COLUMN slug VARCHAR(255) UNIQUE;
ALTER TABLE assignments ADD COLUMN metadata JSONB NOT NULL DEFAULT '{}';
ALTER TABLE assignments ADD COLUMN deadline TIMESTAMPTZ;
ALTER TABLE assignments ADD CONSTRAINT assignment_status_check CHECK (status IN ('ACTIVE','INACTIVE'));
ALTER TABLE assignment_attempts ADD COLUMN solution TEXT NOT NULL DEFAULT '';
ALTER TABLE assignment_attempts ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE assignment_attempts ADD CONSTRAINT attempt_status_check CHECK (status IN ('STARTING','RUNNING','TESTED','FAILED','SUBMITTED'));
ALTER TABLE submissions ADD CONSTRAINT unique_submission_attempt UNIQUE(attempt_id);
ALTER TABLE submissions ADD CONSTRAINT submission_status_check CHECK (status IN ('SUBMITTED','REVIEWED','RETURNED','REJECTED'));
CREATE TABLE assignment_test_cases (
 id UUID PRIMARY KEY, assignment_id UUID NOT NULL REFERENCES assignments(id),
 name VARCHAR(255) NOT NULL, type VARCHAR(255) NOT NULL, weight INTEGER NOT NULL CHECK(weight BETWEEN 1 AND 100),
 enabled BOOLEAN NOT NULL DEFAULT TRUE, configuration JSONB NOT NULL,
 UNIQUE(assignment_id,name)
);
CREATE TABLE submission_test_results (
 id UUID PRIMARY KEY, attempt_id UUID NOT NULL REFERENCES assignment_attempts(id),
 submission_id UUID REFERENCES submissions(id), test_case_id UUID NOT NULL REFERENCES assignment_test_cases(id),
 passed BOOLEAN NOT NULL, output TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 UNIQUE(attempt_id,test_case_id)
);
CREATE TABLE faculty_reviews (
 id UUID PRIMARY KEY, submission_id UUID NOT NULL REFERENCES submissions(id), faculty_id UUID NOT NULL REFERENCES users(id),
 grade NUMERIC(5,2) CHECK(grade BETWEEN 0 AND 100), feedback TEXT NOT NULL, status VARCHAR(255) NOT NULL,
 created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE network_servers (
 id UUID PRIMARY KEY, name VARCHAR(255) NOT NULL, service VARCHAR(255) NOT NULL UNIQUE, address VARCHAR(255) NOT NULL,
 port INTEGER NOT NULL CHECK(port BETWEEN 0 AND 65535), protocol VARCHAR(255) NOT NULL, status VARCHAR(255) NOT NULL,
 last_heartbeat TIMESTAMPTZ
);
CREATE TABLE network_sessions (
 id UUID PRIMARY KEY, attempt_id UUID NOT NULL UNIQUE REFERENCES assignment_attempts(id),
 server_id UUID NOT NULL REFERENCES network_servers(id), status VARCHAR(255) NOT NULL,
 started_at TIMESTAMPTZ NOT NULL DEFAULT now(), ended_at TIMESTAMPTZ
);
CREATE TABLE audit_logs (
 id UUID PRIMARY KEY, actor_id UUID REFERENCES users(id), action VARCHAR(255) NOT NULL,
 resource VARCHAR(255) NOT NULL, details TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX cases_assignment_idx ON assignment_test_cases(assignment_id);
CREATE INDEX results_submission_idx ON submission_test_results(submission_id);
CREATE INDEX reviews_submission_idx ON faculty_reviews(submission_id);
CREATE INDEX submissions_student_idx ON submissions(student_id,submitted_at);
CREATE INDEX attempts_started_idx ON assignment_attempts(started_at);
CREATE INDEX audit_created_idx ON audit_logs(created_at);
INSERT INTO assignments(id,title,description,protocol,difficulty,status,slug,requirements,concepts,metadata) VALUES ('00000000-0000-4000-8000-000000000001','TCP Chat Client','Build a college messaging client with a username handshake, multiple messages and graceful disconnection.','TCP','EASY','ACTIVE','tcp-chat','["Handshake with USER <name>","Send MSG <text> and read each reply","QUIT gracefully; catch connection failures"]'::jsonb,'["TCP","Sockets","Connection lifecycle"]'::jsonb,'{"objective":"Build a college messaging client with a username handshake, multiple messages and graceful disconnection.","constraints":["JavaScript solve(input) runs in an isolated interpreter","15 seconds per test, 16 MiB memory, 60 network operations","Only the supplied LabLink network services are accessible"],"instructions":["Read the protocol and capability API","Implement solve(input) for every test input","Run to inspect output, then Test before submitting"],"expectedBehavior":"Return {welcome, replies, closed:true} for input.username/messages. On input.service=''offline'', return {error:true}. Treat QUIT as a server disconnect and close your socket.","starterCode":"function solve(input) {\n  // Implement the requirements using the capability API below.\n  print(input);\n  return {};\n}","serverRequirement":"Controlled TCP tcp-chat service","capabilityApi":"tcp.connect(''chat''|''file''|''search''|''offline''), tcp.send(id,line), tcp.read(id), tcp.close(id); udp.exchange(updates); http.request(path,method); http.probe(name); dns.lookup(name); save(name,content); sha256(content); print(value). All calls are synchronous inside the isolated interpreter."}'::jsonb);
INSERT INTO assignment_test_cases(id,assignment_id,name,type,weight,configuration) VALUES (gen_random_uuid(),'00000000-0000-4000-8000-000000000001','Handshake and message','tcp-chat',35,'{"input":{"service":"chat","username":"Ada","messages":["Hello"]}}'::jsonb);
INSERT INTO assignment_test_cases(id,assignment_id,name,type,weight,configuration) VALUES (gen_random_uuid(),'00000000-0000-4000-8000-000000000001','Multiple messages and disconnect','tcp-chat',40,'{"input":{"service":"chat","username":"Lin","messages":["first","second","third"]}}'::jsonb);
INSERT INTO assignment_test_cases(id,assignment_id,name,type,weight,configuration) VALUES (gen_random_uuid(),'00000000-0000-4000-8000-000000000001','Connection failure','tcp-chat',25,'{"input":{"service":"offline","username":"Test","messages":[]}}'::jsonb);
