INSERT INTO assignments(id,title,description,protocol,difficulty,status,slug,requirements,concepts,metadata) VALUES ('00000000-0000-4000-8000-000000000002','Reliable File Transfer','Receive, save and verify a requested file through a real TCP stream.','TCP','MEDIUM','ACTIVE','file-transfer','["Send GET <filename>","Parse JSON header and all DATA chunks until END","Save the reconstructed file and verify SHA-256","Handle missing and interrupted transfers"]'::jsonb,'["Streams","Buffering","Integrity"]'::jsonb,'{"objective":"Receive, save and verify a requested file through a real TCP stream.","constraints":["JavaScript solve(input) runs in an isolated interpreter","15 seconds per test, 16 MiB memory, 60 network operations","Only the supplied LabLink network services are accessible"],"instructions":["Read the protocol and capability API","Implement solve(input) for every test input","Run to inspect output, then Test before submitting"],"expectedBehavior":"Server lines: {name,bytes,sha256}, DATA <base64>, END. Errors: ERROR NOT_FOUND. An interrupted transfer closes before END. Return {name,content,sha256,saved:true}; errors {error:true}. Use save(name,content) and sha256(content).","starterCode":"function solve(input) {\n  // Implement the requirements using the capability API below.\n  print(input);\n  return {};\n}","serverRequirement":"Controlled TCP file-transfer service","capabilityApi":"tcp.connect(''chat''|''file''|''search''|''offline''), tcp.send(id,line), tcp.read(id), tcp.close(id); udp.exchange(updates); http.request(path,method); http.probe(name); dns.lookup(name); save(name,content); sha256(content); print(value). All calls are synchronous inside the isolated interpreter."}'::jsonb);
