INSERT INTO assignments(id,title,description,protocol,difficulty,status,slug,requirements,concepts,metadata) VALUES ('00000000-0000-4000-8000-000000000003','UDP Multiplayer Position & Telemetry System','Send player coordinates and process broadcast updates while rejecting stale packets.','UDP','MEDIUM','ACTIVE','udp-telemetry','["Send actual UDP datagrams using udp.exchange","Track positions for every player","Keep only the highest sequence for each player"]'::jsonb,'["Datagrams","Packet loss","Sequence numbers"]'::jsonb,'{"objective":"Send player coordinates and process broadcast updates while rejecting stale packets.","constraints":["JavaScript solve(input) runs in an isolated interpreter","15 seconds per test, 16 MiB memory, 60 network operations","Only the supplied LabLink network services are accessible"],"instructions":["Read the protocol and capability API","Implement solve(input) for every test input","Run to inspect output, then Test before submitting"],"expectedBehavior":"Call udp.exchange(input.updates) once. It returns received datagrams including broadcasts and an intentionally stale packet. Return {positions:{player:{x,y,seq}}}; use sequence comparison, never arrival order.","starterCode":"function solve(input) {\n  // Implement the requirements using the capability API below.\n  print(input);\n  return {};\n}","serverRequirement":"Controlled UDP udp-telemetry service","capabilityApi":"tcp.connect(''chat''|''file''|''search''|''offline''), tcp.send(id,line), tcp.read(id), tcp.close(id); udp.exchange(updates); http.request(path,method); http.probe(name); dns.lookup(name); save(name,content); sha256(content); print(value). All calls are synchronous inside the isolated interpreter."}'::jsonb);
