INSERT INTO assignments(id,title,description,protocol,difficulty,status,slug,requirements,concepts,metadata) VALUES ('00000000-0000-4000-8000-000000000004','College Student Information API Client','Retrieve and display student records, validating HTTP status before parsing JSON.','HTTP','EASY','ACTIVE','http-api','["GET the configured student path","Parse response JSON","Return name, rollNumber, department and attendance","Handle 4xx and 5xx explicitly"]'::jsonb,'["HTTP","Status codes","REST","JSON"]'::jsonb,'{"objective":"Retrieve and display student records, validating HTTP status before parsing JSON.","constraints":["JavaScript solve(input) runs in an isolated interpreter","15 seconds per test, 16 MiB memory, 60 network operations","Only the supplied LabLink network services are accessible"],"instructions":["Read the protocol and capability API","Implement solve(input) for every test input","Run to inspect output, then Test before submitting"],"expectedBehavior":"http.request(path,''GET'') returns {status,body,latencyMs}. Parse successful body and return all four student fields. Errors return {error:true,status}. Inputs specify path.","starterCode":"function solve(input) {\n  // Implement the requirements using the capability API below.\n  print(input);\n  return {};\n}","serverRequirement":"Controlled HTTP http-api service","capabilityApi":"tcp.connect(''chat''|''file''|''search''|''offline''), tcp.send(id,line), tcp.read(id), tcp.close(id); udp.exchange(updates); http.request(path,method); http.probe(name); dns.lookup(name); save(name,content); sha256(content); print(value). All calls are synchronous inside the isolated interpreter."}'::jsonb);
