INSERT INTO assignments(id,title,description,protocol,difficulty,status,slug,requirements,concepts,metadata) VALUES ('00000000-0000-4000-8000-000000000005','DNS Troubleshooting Challenge','Investigate why portal.lablink.edu does not open using a controlled DNS resolver and actual reachability checks.','DNS','MEDIUM','ACTIVE','dns-troubleshooting','["Query the affected and working names","Compare DNS answers with endpoint reachability","Record observations, evidence, root cause and recommended fix"]'::jsonb,'["DNS","A records","Resolution","Troubleshooting"]'::jsonb,'{"objective":"Investigate why portal.lablink.edu does not open using a controlled DNS resolver and actual reachability checks.","constraints":["JavaScript solve(input) runs in an isolated interpreter","15 seconds per test, 16 MiB memory, 60 network operations","Only the supplied LabLink network services are accessible"],"instructions":["Read the protocol and capability API","Implement solve(input) for every test input","Run to inspect output, then Test before submitting"],"expectedBehavior":"Use dns.lookup(name) (real UDP DNS query) and http.probe(''portal'' or ''resolved''). The portal A record is deliberately misconfigured. solve(input) returns {observations,dnsInformation,evidence,rootCause,recommendedFix}, with evidence from your calls. Diagnose a wrong A record and recommend correcting it to the reachable address.","starterCode":"function solve(input) {\n  // Query DNS, check reachability, and return your diagnosis with evidence.\n  print(dns.lookup(input.name));\n  return { observations: \"\", dnsInformation: \"\", evidence: \"\", rootCause: \"\", recommendedFix: \"\" };\n}","serverRequirement":"Controlled DNS dns-troubleshooting service","capabilityApi":"tcp.connect(''chat''|''file''|''search''|''offline''), tcp.send(id,line), tcp.read(id), tcp.close(id); udp.exchange(updates); http.request(path,method); http.probe(name); dns.lookup(name); save(name,content); sha256(content); print(value). All calls are synchronous inside the isolated interpreter."}'::jsonb);
INSERT INTO assignment_test_cases(id,assignment_id,name,type,weight,configuration) VALUES (gen_random_uuid(),'00000000-0000-4000-8000-000000000005','DNS investigation','dns-troubleshooting',35,'{"input":{"name":"portal.lablink.edu","comparison":"working.lablink.edu"}}'::jsonb);
INSERT INTO assignment_test_cases(id,assignment_id,name,type,weight,configuration) VALUES (gen_random_uuid(),'00000000-0000-4000-8000-000000000005','Reachability evidence','dns-troubleshooting',30,'{"input":{"name":"portal.lablink.edu","comparison":"working.lablink.edu"}}'::jsonb);
INSERT INTO assignment_test_cases(id,assignment_id,name,type,weight,configuration) VALUES (gen_random_uuid(),'00000000-0000-4000-8000-000000000005','Diagnosis and repair recommendation','dns-troubleshooting',35,'{"input":{"name":"portal.lablink.edu","comparison":"working.lablink.edu"}}'::jsonb);
