INSERT INTO assignments(id,title,description,protocol,difficulty,status,slug,requirements,concepts,metadata) VALUES ('00000000-0000-4000-8000-000000000006','Network Monitoring System','Measure configured college services, reporting availability and real elapsed latency.','HTTP','MEDIUM','ACTIVE','network-monitor','["Probe each configured service","Distinguish an HTTP failure, refused connection and timeout","Return availability and measured latency"]'::jsonb,'["Availability","Latency","Timeouts","Monitoring"]'::jsonb,'{"objective":"Measure configured college services, reporting availability and real elapsed latency.","constraints":["JavaScript solve(input) runs in an isolated interpreter","15 seconds per test, 16 MiB memory, 60 network operations","Only the supplied LabLink network services are accessible"],"instructions":["Read the protocol and capability API","Implement solve(input) for every test input","Run to inspect output, then Test before submitting"],"expectedBehavior":"Use http.probe(name), with names lab,file,database,web,slow. Return {servers:[{name,status:''ONLINE''|''OFFLINE'',latencyMs,reason}]}. Classify non-2xx, refusals and timeouts as OFFLINE. timeout input is handled by the capability.","starterCode":"function solve(input) {\n  // Implement the requirements using the capability API below.\n  print(input);\n  return {};\n}","serverRequirement":"Controlled HTTP network-monitor service","capabilityApi":"tcp.connect(''chat''|''file''|''search''|''offline''), tcp.send(id,line), tcp.read(id), tcp.close(id); udp.exchange(updates); http.request(path,method); http.probe(name); dns.lookup(name); save(name,content); sha256(content); print(value). All calls are synchronous inside the isolated interpreter."}'::jsonb);
INSERT INTO assignment_test_cases(id,assignment_id,name,type,weight,configuration) VALUES (gen_random_uuid(),'00000000-0000-4000-8000-000000000006','Online endpoints','network-monitor',35,'{"input":{"servers":["lab","file","web"]}}'::jsonb);
