INSERT INTO assignments(id,title,description,protocol,difficulty,status,slug,requirements,concepts,metadata) VALUES ('00000000-0000-4000-8000-000000000007','Client-Server File Search','Search a central document server and download a chosen matching file.','TCP','MEDIUM','ACTIVE','file-search','["Send SEARCH <query> and parse matching files","Send GET <selected filename>","Decode and save the file","Handle empty results and invalid selection"]'::jsonb,'["TCP","Request/response","Search","File transfer"]'::jsonb,'{"objective":"Search a central document server and download a chosen matching file.","constraints":["JavaScript solve(input) runs in an isolated interpreter","15 seconds per test, 16 MiB memory, 60 network operations","Only the supplied LabLink network services are accessible"],"instructions":["Read the protocol and capability API","Implement solve(input) for every test input","Run to inspect output, then Test before submitting"],"expectedBehavior":"Connect to search. SEARCH <query> returns a JSON array of filenames. GET <filename> returns JSON {name,content,sha256} or {error:''NOT_FOUND''}. Return {results,name,content,saved:true}; empty results {results:[]}; invalid selection {results,error:true}. save(name,content) records the download.","starterCode":"function solve(input) {\n  // Implement the requirements using the capability API below.\n  print(input);\n  return {};\n}","serverRequirement":"Controlled TCP file-search service","capabilityApi":"tcp.connect(''chat''|''file''|''search''|''offline''), tcp.send(id,line), tcp.read(id), tcp.close(id); udp.exchange(updates); http.request(path,method); http.probe(name); dns.lookup(name); save(name,content); sha256(content); print(value). All calls are synchronous inside the isolated interpreter."}'::jsonb);
